/// <summary>
/// AVAListZ4Mark class
/// </summary>
class AVAListZ4Mark extends RunBase
{
    QueryRun            queryRun;
    AVAListZ4Data      listZ4Data;
    AVAListZ4Status    listStatus;

    #DEFINE.CurrentVersion(1)
    #LOCALMACRO.CurrentList
        listStatus
    #ENDMACRO

}

Method.Source:
/// <summary>
///    Returns a class that contains the methods that are described by the <c>RunBaseDialogable</c>
///    interface.
/// </summary>
/// <returns>
///    A class that contains the methods that are described by the <c>RunBaseDialogable</c> interface.
/// </returns>
/// <remarks>
///    A dialog can be either built by using the <c>Dialog</c> class or by using a class that is created
///    in the Application Object Tree (AOT).
/// </remarks>
Object dialog()
{
    DialogRunbase       dialog = super();

    return dialog;
}

public boolean init()
{
    str             statusValue;
    QueryBuildRange queryBuildRange;
    boolean         ret = super();

    switch(listStatus)
    {
        case AVAListZ4Status::New:
            statusValue = queryValue(AVAListZ4Status::Reported);
            break;
        case AVAListZ4Status::Reported:
            statusValue = queryValue(AVAListZ4Status::New);
            break;
    }

    queryBuildRange = SysQuery::findOrCreateRange(queryRun.query().dataSourceTable(tableNum(AVAListZ4Data)), fieldnum(AVAListZ4Data, Status));
    queryBuildRange.value(statusValue);

    return ret;
}

protected void new()
{
    super();

    queryRun = new QueryRun(querystr(AVAListZ4));
    queryRun.query().dataSourceTable(tableNum(AVAListZ4Data)).addRange(fieldnum(AVAListZ4Data, DispatchId));
}

public AVAListZ4Status parmListStatus(AVAListZ4Status _listStatus = listStatus)
{
    listStatus = _listStatus;
    return listStatus;
}

/// <summary>
///    Retrieves the instance of the <c>QueryRun</c> class, which is used by the <c>queryPrompt</c> method.
/// </summary>
/// <returns>
///    The instance of the <c>QueryRun</c> class, which is used by the <c>queryPrompt</c> method.
/// </returns>
/// <remarks>
///    This method is used if a query prompt is the dialog, and if a Select menu item is added to a
///    dialog. Do not create the instance of the <c>QueryRun</c> class when this method is called. Do it
///    in the <c>unpack</c> method and the <c>initParmDefault</c> method, or in the <c>init</c> method.
/// </remarks>
public QueryRun queryRun()
{
    return  queryRun;
}

/// <summary>
///    Contains the code that does the actual job of the class.
/// </summary>
void run()
{
    ttsbegin;

    while (queryRun.next())
    {
        listZ4Data = queryRun.get(tablenum(AVAListZ4Data));
        listZ4Data.selectForUpdate(true);

        switch(listStatus)
        {
            case AVAListZ4Status::New:
                listZ4Data.status = AVAListZ4Status::New;
                break;

            case AVAListZ4Status::Reported:
                listZ4Data.status = AVAListZ4Status::Reported;
                break;
        }

        listZ4Data.doUpdate();
    }

    ttscommit;
}

public boolean unpack(container packedClass)
{
    Integer     version = conpeek(packedClass,1);
    container   packedQuery;

    switch (version)
    {
        case #CurrentVersion:
            [version,#CurrentList,packedQuery] = packedClass;
            if (packedQuery)
            {
                queryRun = new QueryRun(packedQuery);
            }
            break;
        default:
            return false;
    }

    return true;
}

static void main(Args args)
{
    AVAListZ4Mark  listMark = new AVAListZ4Mark();
    FormDataSource  fds;

    if (args)
    {
        if (args.record())
        {
            fds = FormDataUtil::getFormDataSource(args.record());
        }

        listMark.parmListStatus(args.parmEnum());
    }

    listMark.init();

    if (listMark.prompt())
    {
        listMark.runOperation();

        if (fds)
        {
            fds.executeQuery();
        }
    }
}
